-- Supabase Schema Teardown. Generated by tools/build_sql.py; edit there, not here.

create table public.known_issues (
  id       int primary key,
  severity text not null default 'warning',
  title    text not null,
  detail   text not null,
  hint     text
);
alter table public.known_issues enable row level security;
create policy "Public read" on public.known_issues for select to anon, authenticated using (true);

insert into public.known_issues (id, title, detail, hint) values
  (1, 'insecure defaults in AI-built apps', 'In 2025 a researcher scanned 1,645 Lovable showcase apps and found about 170 with Supabase tables open to anyone holding the public key, because Row Level Security was never switched on (CVE-2025-48757). The flaw was in how apps were generated, but anyone who can ship a backend can ship an open one. On Hacker News, "Supabase MCP can leak your entire SQL database" (July 2025) drew 848 points and 470 comments, more discussion than almost anything Supabase posted itself.', 'HINT: enable RLS on every table. Yes, every one.'),
  (2, 'concentration risk', 'If agents create most new databases and one agent is the biggest source, growth depends on another company''s roadmap. App builders are launching their own backends: Bolt Cloud, Replit, Lovable Cloud (which runs on Supabase today).', null),
  (3, 'free databases are not revenue', 'Millions of agent-created databases are free and short-lived. The business depends on converting a small slice into paid production workloads.', null),
  (4, 'developer experience gaps', 'Drift between local and hosted environments, migrations, auth edge cases, and no long-running client transactions, which pushes logic into database functions.', null),
  (5, 'becoming the default is partly luck', 'Copplestone''s own view: if agents settle on two or three defaults per category, most dev tools won''t be one of them, and you can''t plan for that. You do the fundamentals for word of mouth and ease of use, and hope. Against AWS, the last advantage may simply be the vibes.', 'HINT: he''s not joking about the vibes.');
